<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\Job;use App\Models\JobApplication;use App\Services\CandidateJobMatcher;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class CandidateMatchController extends Controller{public function candidate(Request $request,Job $job,CandidateJobMatcher $matcher):JsonResponse{abort_unless($request->user()->account_type==='candidate',403);$profile=$request->user()->candidateProfile;abort_unless($profile,422,'Completa primero tu perfil.');$application=new JobApplication(['profile_snapshot'=>['profile'=>$profile->toArray()]]);$application->setRelation('job',$job);return response()->json(['data'=>$matcher->analyze($application)]);}public function company(Request $request,JobApplication $application,CandidateJobMatcher $matcher):JsonResponse{abort_unless($request->user()->account_type==='company',403);$company=$request->user()->companies()->wherePivot('status','active')->whereKey($application->job->company_id)->first();abort_unless($company,404);return response()->json(['data'=>$matcher->analyze($application)]);}}
